//! macOS settings: the values powermise asks mise to manage live in one
//! generated file, `conf.d/powermise-macos.toml`, as
//! `[bootstrap.macos.defaults."<domain>"] <key> = <value>`. mise applies it
//! with `mise bootstrap --only macos-defaults`. (`mise config set` can't
//! address domains with dots in them, so powermise writes this one file
//! itself — the same way AI Setups write theirs.)
use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
    process::{Command, Stdio},
};

use serde::{Deserialize, Serialize};

use crate::{CommandResult, message, mise_config_dir};

/// Apps the catalog may ask to relaunch after a change.
pub(crate) const RELAUNCHABLE: &[&str] = &[
    "Activity Monitor",
    "Dock",
    "Finder",
    "Messages",
    "Music",
    "Safari",
    "SystemUIServer",
    "Terminal",
    "TextEdit",
    "Xcode",
];

fn fragment_path() -> CommandResult<PathBuf> {
    Ok(mise_config_dir()?.join("conf.d/powermise-macos.toml"))
}

/// Preference domains and keys: reverse-DNS names and plain identifiers.
fn valid_name(name: &str) -> bool {
    !name.is_empty()
        && !name.starts_with('-')
        && name
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || "._-".contains(character))
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct PreferenceKey {
    domain: String,
    key: String,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ManagedDefault {
    domain: String,
    key: String,
    value: serde_json::Value,
}

type Defaults = BTreeMap<String, BTreeMap<String, toml::Value>>;

fn read_fragment(path: &Path) -> CommandResult<Defaults> {
    let contents = match std::fs::read_to_string(path) {
        Ok(contents) => contents,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Defaults::new()),
        Err(error) => return Err(message(error)),
    };
    let table: toml::Table = contents.parse().map_err(message)?;
    Ok(table
        .get("bootstrap")
        .and_then(|bootstrap| bootstrap.get("macos"))
        .and_then(|macos| macos.get("defaults"))
        .and_then(toml::Value::as_table)
        .map(|domains| {
            domains
                .iter()
                .filter_map(|(domain, keys)| {
                    let keys = keys.as_table()?;
                    Some((
                        domain.clone(),
                        keys.iter()
                            .map(|(key, value)| (key.clone(), value.clone()))
                            .collect(),
                    ))
                })
                .collect()
        })
        .unwrap_or_default())
}

fn write_fragment(path: &Path, defaults: &Defaults) -> CommandResult<()> {
    if defaults.values().all(BTreeMap::is_empty) {
        return match std::fs::remove_file(path) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(message(error)),
        };
    }
    let mut domains = toml::Table::new();
    for (domain, keys) in defaults.iter().filter(|(_, keys)| !keys.is_empty()) {
        domains.insert(
            domain.clone(),
            toml::Value::Table(
                keys.iter()
                    .map(|(key, value)| (key.clone(), value.clone()))
                    .collect(),
            ),
        );
    }
    let mut macos = toml::Table::new();
    macos.insert("defaults".into(), toml::Value::Table(domains));
    let mut bootstrap = toml::Table::new();
    bootstrap.insert("macos".into(), toml::Value::Table(macos));
    let mut root = toml::Table::new();
    root.insert("bootstrap".into(), toml::Value::Table(bootstrap));
    let body = toml::to_string(&root).map_err(message)?;
    let contents = format!(
        "# Generated by powermise: macOS settings you chose in the app. Edit them\n\
         # there; mise applies them with `mise bootstrap --only macos-defaults`.\n\
         # Deleting this file stops managing them (the values stay as they are).\n\n{body}"
    );
    powermise_state::write_atomically(path, contents.as_bytes()).map_err(message)?;
    Ok(())
}

fn managed(defaults: &Defaults) -> Vec<ManagedDefault> {
    defaults
        .iter()
        .flat_map(|(domain, keys)| {
            keys.iter().map(move |(key, value)| ManagedDefault {
                domain: domain.clone(),
                key: key.clone(),
                value: serde_json::to_value(value).unwrap_or(serde_json::Value::Null),
            })
        })
        .collect()
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MacosState {
    /// What powermise's file asks mise to set.
    managed: Vec<ManagedDefault>,
    /// What macOS has now, per requested key (`defaults read`), or `None`
    /// when it isn't set (macOS's built-in default applies).
    current: Vec<Option<String>>,
    fragment_path: PathBuf,
}

/// The managed settings and the current values of `keys`.
#[tauri::command]
pub async fn macos_settings(keys: Vec<PreferenceKey>) -> CommandResult<MacosState> {
    tauri::async_runtime::spawn_blocking(move || {
        let current = keys
            .iter()
            .map(|entry| {
                if !cfg!(target_os = "macos")
                    || !valid_name(&entry.domain)
                    || !valid_name(&entry.key)
                {
                    return None;
                }
                let output = Command::new("defaults")
                    .args(["read", &entry.domain, &entry.key])
                    .stdin(Stdio::null())
                    .output()
                    .ok()?;
                output
                    .status
                    .success()
                    .then(|| String::from_utf8_lossy(&output.stdout).trim().to_owned())
            })
            .collect();
        Ok(MacosState {
            managed: managed(&read_fragment(&fragment_path()?)?),
            current,
            fragment_path: fragment_path()?,
        })
    })
    .await
    .map_err(message)?
}

/// Asks mise to manage one setting (or, with `value: null`, stop managing
/// it). Writes powermise's file only; applying is `mise bootstrap`.
#[tauri::command]
pub fn set_macos_default(
    domain: String,
    key: String,
    value: Option<serde_json::Value>,
) -> CommandResult<Vec<ManagedDefault>> {
    if !valid_name(&domain) || !valid_name(&key) {
        return Err(format!(
            "`{domain} {key}` isn't a preference powermise can set"
        ));
    }
    let path = fragment_path()?;
    let mut defaults = read_fragment(&path)?;
    match value {
        None => {
            if let Some(keys) = defaults.get_mut(&domain) {
                keys.remove(&key);
            }
        }
        Some(value) => {
            let value = match value {
                serde_json::Value::Bool(flag) => toml::Value::Boolean(flag),
                serde_json::Value::Number(number) => match number.as_i64() {
                    Some(integer) => toml::Value::Integer(integer),
                    None => {
                        toml::Value::Float(number.as_f64().ok_or("that number is out of range")?)
                    }
                },
                serde_json::Value::String(text) if !text.chars().any(char::is_control) => {
                    toml::Value::String(text)
                }
                _ => return Err("macOS settings take true/false, a number, or text".into()),
            };
            defaults.entry(domain).or_default().insert(key, value);
        }
    }
    write_fragment(&path, &defaults)?;
    Ok(managed(&defaults))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_fragment_round_trips_and_disappears_when_empty() {
        let directory =
            std::env::temp_dir().join(format!("powermise-macos-{}", std::process::id()));
        let path = directory.join("conf.d/powermise-macos.toml");
        let mut defaults = Defaults::new();
        defaults
            .entry("com.apple.dock".into())
            .or_default()
            .insert("autohide".into(), toml::Value::Boolean(true));
        defaults
            .entry("NSGlobalDomain".into())
            .or_default()
            .insert("KeyRepeat".into(), toml::Value::Integer(2));
        write_fragment(&path, &defaults).unwrap();
        let contents = std::fs::read_to_string(&path).unwrap();
        assert!(
            contents.contains("[bootstrap.macos.defaults.\"com.apple.dock\"]"),
            "{contents}"
        );
        assert_eq!(read_fragment(&path).unwrap(), defaults);
        write_fragment(&path, &Defaults::new()).unwrap();
        assert!(!path.exists());
        let _ = std::fs::remove_dir_all(directory);
    }

    #[test]
    fn names_are_checked() {
        assert!(valid_name("com.apple.dock"));
        assert!(valid_name("com.apple.mouse.scaling"));
        assert!(!valid_name("-g"));
        assert!(!valid_name("a b"));
    }
}
